	hasRiskReview := false
	if rrev, ok, err := s.db.LatestProductRiskReview(ctx, product.ProductKey); err == nil && ok && rrev.ProductKey != "" {
		hasRiskReview = true
	}

	// Fetch Masking Configured
	now := time.Now().UTC()
	// applyMasking runs per contract, so the product only answers masked while every contract
	// that can still serve it carries a policy the runtime enforces. Counting a single masked
	// contract as evidence published sensitive products whose other customers kept receiving
	// raw values, and free-form policy text masks nothing at all. Contracts that can never
	// serve again are ignored, and a listing error is no evidence either way.
	maskingConfigured := false
	scopes, err := s.db.ListContractScopes(ctx, product.ProductKey, "")
	if err == nil {
		maskingConfigured = true
		for _, sc := range scopes {
			if contractScopeCanServe(sc, now) && !maskingPolicyMasks(sc.MaskingPolicy) {
				maskingConfigured = false
				break
			}
		}
	}

	return dw.EvaluatePublishGateV2(product, readiness, approvals, packPtr, slaPtr, costPtr, qualityResults, hasRiskReview, maskingConfigured, now), nil
}

// dataWorksTimestampOK rejects an optional access-window timestamp the runtime gate cannot parse.
// entitlementActive and contractScopeActive treat an unparseable value as inactive, so storing one
// would publish an access rule that silently denies every query while the admin views call it active.
func dataWorksTimestampOK(w http.ResponseWriter, field, raw string) bool {
	if raw == "" {
		return true
	}
	if _, err := time.Parse(time.RFC3339Nano, raw); err != nil {
		writeOpenAIError(w, http.StatusBadRequest, field+" must be an RFC3339 timestamp", "invalid_request_error", "invalid_"+field)
		return false
	}
	return true
}

// dataWorksAccessWindowOrdered rejects an access window that closes before it opens.
// contractScopeActive requires now to sit inside the window, so an inverted one denies every
// query for the whole life of the contract while the admin views list it as an active contract.
// Both values are already known to parse when this runs; an unparseable one is reported by
// dataWorksTimestampOK instead.
func dataWorksAccessWindowOrdered(w http.ResponseWriter, from, to string) bool {
	if from == "" || to == "" {
		return true
	}
	validFrom, err := time.Parse(time.RFC3339Nano, from)
	if err != nil {
		return true
	}
	validTo, err := time.Parse(time.RFC3339Nano, to)
	}
	for _, trace := range approvals {
		approvalNode := "approval:" + trace.ID
		nodes = append(nodes, map[string]any{"id": approvalNode, "type": "approval", "label": trace.Step, "status": trace.Status, "required": trace.Required})
		edges = append(edges, map[string]any{"from": "product:" + trace.ProductKey, "to": approvalNode, "type": "approval_trace"})
	}
	return map[string]any{"nodes": nodes, "edges": edges}
}

